import{_ as e,o as a,c as t,a2 as r}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"启动故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/boot-failures.md","filePath":"zh/troubleshooting/boot-failures.md"}'),l={name:"zh/troubleshooting/boot-failures.md"};function i(c,o,s,d,n,h){return a(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="启动故障排查" tabindex="-1">启动故障排查 <a class="header-anchor" href="#启动故障排查" aria-label="Permalink to &quot;启动故障排查&quot;">​</a></h1><h2 id="启动日志是一份检查单" tabindex="-1">启动日志是一份检查单 <a class="header-anchor" href="#启动日志是一份检查单" aria-label="Permalink to &quot;启动日志是一份检查单&quot;">​</a></h2><p>内核按照点亮顺序（顺序见 <a href="./../arch/boot-flow.html">arch/boot-flow.md</a>）为每个子系统打印一行。诊断方法：</p><ol><li><strong>串口完全无输出</strong> - GRUB 未运行或 ISO 条目错误。尝试启动 ISO 的其他槽位条目；比较 BIOS 与 UEFI 模式。</li><li><strong>在 <code>long mode entry OK</code> 之前停止</strong> - boot.S 阶段：multiboot2 握手失败（magic/mbi 错误）- 使用 <code>-serial file:</code> 捕获并检查 mbi 标签解析。</li><li><strong>在某个驱动行停止</strong> - 该驱动家族在您的硬件上探测失败；其上一行消息指明了设备。移除该设备（或对应的 QEMU 标志）以确认。</li><li><strong>到达 <code>boot complete</code> 但无提示符</strong> - Shell 初始化；极其罕见（233 命令注册行会是线索）。</li><li><strong>提示符后重启</strong> - 恐慌或看门狗触发：第二次启动后检查 /etc/crashlog（<code>dumpinfo</code>、<code>crashlog</code>），以及事件期间的串口转储。</li></ol><h2 id="自测是你的帮手" tabindex="-1">自测是你的帮手 <a class="header-anchor" href="#自测是你的帮手" aria-label="Permalink to &quot;自测是你的帮手&quot;">​</a></h2><p>启动序列已证明：异常路径（3/3）、Shell 注册（233）、崩溃恢复已就绪。如果这些行已打印，说明底层平台正常 - 检查特定功能，而非平台本身。</p><h2 id="第二次启动分析" tabindex="-1">第二次启动分析 <a class="header-anchor" href="#第二次启动分析" aria-label="Permalink to &quot;第二次启动分析&quot;">​</a></h2><p>A/B 标志与崩溃日志在 /etc 上 survive 重启。任何意外重启后：<code>dmesg</code>（当前启动）、<code>crashlog</code>/<code>dumpinfo</code>（上次启动）、<code>abcfg</code>（GRUB 尝试启动的内容）。</p>',8)])])}const b=e(l,[["render",i]]);export{u as __pageData,b as default};
